<?php require_once __DIR__.'/config/functions.php'; $slug=trim($_GET['slug']??'');$st=db()->prepare("SELECT b.*,c.name category_name,c.slug category_slug FROM blogs b JOIN blog_categories c ON c.id=b.category_id WHERE b.slug=? AND b.status='published' AND b.publish_date<=NOW() LIMIT 1");$st->execute([$slug]);$blog=$st->fetch();if(!$blog){http_response_code(404);$title='Blog Not Found';}else{$title=$blog['meta_title']?:$blog['title'];$description=$blog['meta_description']?:$blog['short_description'];}
$recent=$blog?published_blogs(5,$blog['id']):published_blogs(5);$cats=db()->query("SELECT c.*,COUNT(b.id) total FROM blog_categories c LEFT JOIN blogs b ON b.category_id=c.id AND b.status='published' AND b.publish_date<=NOW() WHERE c.status='active' GROUP BY c.id ORDER BY c.name")->fetchAll();
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?> | VBCCS</title><meta name="description" content="<?=e($description??'VBCCS Editorial')?>"><?php if($blog&&$blog['canonical_url']): ?><link rel="canonical" href="<?=e($blog['canonical_url'])?>"><?php endif; ?><link rel="icon" href="assets/images/favicon.png"><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.8/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.7.2/css/all.min.css" rel="stylesheet"><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="css/style.css"><link rel="stylesheet" href="css/blog.css"></head><body><?php include __DIR__.'/include/header.php'; ?><main class="blog-detail-page"><?php if(!$blog): ?><section class="container py-5"><div class="empty-blog"><h1>Blog not found</h1><a href="editorial.php" class="btn btn-brand mt-3">Back to Editorials</a></div></section><?php else: ?><section class="detail-shell"><div class="container"><div class="row g-5"><article class="col-lg-8"><div class="detail-card"><div class="detail-top"><a class="category-label" href="editorial.php?category=<?=urlencode($blog['category_slug'])?>"><?=e($blog['category_name'])?></a><h1><?=e($blog['title'])?></h1><div class="detail-byline">By <?=e($blog['author'])?> <span>•</span> <?=date('F d, Y',strtotime($blog['publish_date']))?> <span>•</span> <?=e($blog['read_time']?:'5 min read')?></div></div><?php if($blog['featured_image']): ?><img class="detail-featured" src="<?=e($blog['featured_image'])?>" alt="<?=e($blog['title'])?>"><?php endif; ?><div class="article-content"><?= $blog['content'] ?></div></div></article><aside class="col-lg-4"><div class="blog-sidebar detail-sidebar"><div class="sidebar-widget"><h3>Recent Editorials</h3><?php foreach($recent as $r): ?><a class="recent-post" href="blog-detail.php?slug=<?=urlencode($r['slug'])?>"><strong><?=e($r['title'])?></strong><span><?=e($r['short_description'])?></span></a><?php endforeach;?></div><div class="sidebar-widget"><h3>Blog Categories</h3><div class="category-list"><?php foreach($cats as $c): ?><a href="editorial.php?category=<?=urlencode($c['slug'])?>"><?=e($c['name'])?><span><?=$c['total']?></span></a><?php endforeach;?></div></div><div class="sidebar-widget subscribe-widget"><h3>Subscribe to Our Editorial</h3><p>Receive new editorial stories and community updates.</p><form onsubmit="return false"><input type="email" placeholder="Enter your email"><button>Sign Up</button></form></div></div></aside></div></div></section><?php endif;?></main><?php include __DIR__.'/include/footer.php'; ?></body></html>
